<style>
.pos-settings-page{--ps-border:var(--ws-line,#e5e7ee);--ps-card:var(--ws-panel,#fff);--ps-text:var(--ws-text,#182334);--ps-muted:var(--ws-muted,#667085);color:var(--ps-text)}
.pos-settings-header{margin-bottom:22px}.pos-settings-header small{color:var(--ps-muted);font-size:12px}.pos-settings-header h1{margin:8px 0 0;font-size:27px;color:var(--ps-text)}
.pos-settings-card{max-width:1120px;border:1px solid var(--ps-border);border-radius:18px;background:var(--ps-card);overflow:hidden}.pos-settings-heading{padding:24px 24px 0}.pos-settings-heading h2{margin:0;font-size:18px;color:var(--ps-text)}.pos-settings-heading p{margin:8px 0 0;font-size:13px;color:var(--ps-muted)}
.pos-settings-fields{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px;border:0;padding:24px;margin:0;min-width:0}.pos-settings-field{display:flex;flex-direction:column;gap:9px;min-width:0;font-size:13px;font-weight:650}.pos-settings-field select{width:100%;min-width:0;border:1px solid var(--ps-border);border-radius:10px;background:var(--ps-card);color:var(--ps-text);padding:12px;font:inherit;cursor:pointer}.pos-settings-field select:focus-visible,.pos-settings-save:focus-visible{outline:3px solid color-mix(in srgb,var(--primary,#5145e5) 35%,transparent);outline-offset:2px}.pos-settings-field small{font-size:12px;line-height:1.65;font-weight:400;color:var(--ps-muted)}.pos-settings-fields:disabled{opacity:.8}.pos-settings-fields:disabled select{cursor:default}
.pos-settings-note{border-top:1px solid var(--ps-border);padding:16px 24px;margin:0;color:var(--ps-muted);font-size:12px;line-height:1.7;background:var(--ws-bg,#f7f8fb)}.pos-settings-actions{display:flex;justify-content:flex-end;border-top:1px solid var(--ps-border);padding:16px 24px}.pos-settings-save{border:0;border-radius:10px;background:var(--primary,#5145e5);color:#fff;padding:12px 22px;font-weight:700;cursor:pointer}
.pos-settings-message{max-width:1120px;padding:13px 16px;border-radius:10px;margin-bottom:16px;font-size:13px}.pos-settings-success{background:color-mix(in srgb,#16a34a 12%,var(--ps-card));color:var(--ps-text);border:1px solid color-mix(in srgb,#16a34a 35%,var(--ps-border))}.pos-settings-error{background:color-mix(in srgb,#e11d48 10%,var(--ps-card));color:var(--ps-text);border:1px solid color-mix(in srgb,#e11d48 40%,var(--ps-border))}.pos-settings-sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap}
@media(max-width:1050px){.pos-settings-fields{grid-template-columns:1fr;gap:20px}.pos-settings-heading,.pos-settings-fields{padding:20px}.pos-settings-heading{padding-bottom:0}.pos-settings-note{padding:16px 20px}}
</style>
